from pathlib import Path
import json,html
R=Path('docs/coach/phase13');m=json.loads((R/'markers-report.json').read_text())
rows=''.join('<tr><td>'+html.escape(x['name'])+'</td><td>'+x['region']+'</td><td>'+', '.join(f'{v:.3f}' for v in x['staticMedianM'])+'</td><td>'+str(x['missingSamples'])+'</td><td>'+str(len(x['jumpFlagsOver50mm']))+'</td></tr>' for x in m['markers'])
s='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>PARISFIT · Phase13 Michaud</title><style>*{box-sizing:border-box}body{overflow-wrap:anywhere;margin:0;background:#edf5ef;color:#163f32;font:16px/1.6 system-ui}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:clamp(28px,5vw,48px);line-height:1.15}h2{margin-top:36px}a{color:#165d47;overflow-wrap:anywhere}.tag{background:#f7d5c9;padding:8px 14px;border-radius:20px;display:inline-block}section{background:white;padding:22px;margin:20px 0;border-radius:16px}video,img{width:100%;height:auto}button{padding:12px;border:1px solid #165d47;background:#edf5ef;border-radius:8px;color:#163f32;font:inherit;cursor:pointer}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd}td:first-child{overflow-wrap:anywhere}footer{font-size:14px}code{overflow-wrap:anywhere}</style><main><a href="../phase12/index.html">← Phase12 · sources</a><p>PARISFIT / RECHERCHE COACH / PHASE13</p><h1>Des marqueurs au squelette :<br>ce qui est mesuré, ce qui reste à prouver.</h1><p class="tag">Reconstruction anatomique non admise · aucun retarget</p><p>S01 · P001 · répétition1. Les chaînes ci-dessous sont des diagnostics, pas un remplacement humain de Rocketbox.</p><section><h2>Trois réponses explicites</h2><p><b>Source suffisante ? EN ATTENTE DE VALIDATION HUMAINE.</b> Intégrité et temporalité des fichiers vérifiées. Calibration physique et registration anatomique encore à qualifier.</p><p><b>Squelette cohérent ? EN ATTENTE DE VALIDATION HUMAINE.</b> H0/H1/H2 sont REFUSÉS comme squelettes anatomiques ; une longueur imposée n'est pas une preuve.</p><p><b>Transfert sans dégradation ? NON TESTÉ.</b> Aucun GLB généré, aucune animation activée. Rocketbox et les huit exercices sont inchangés.</p></section><section><h2>Pourquoi ne pas retargeter ces chaînes ?</h2><p>La distance entre landmarks de cuisse varie d'environ80mm. Fixer leur longueur déplace les endpoints : résidu RMS46,5mm pourH1 et86,8mm pourH2. Le fit de bassin de2,1mm ne localise pas les centres de hanche.</p><p>OpenSim4.6 charge le template :22corps,39coordonnées,66marqueurs. Aucun nom strictement identique aux37labelsCSV. La correspondance et le scaling ne sont pas validés ; le chargement n'est pas une IK du sujet.</p></section><section><h2>Cycle et forces</h2><p>10,45s → bas11,08s →11,94s. Descente puis remontée observables. Pas de préparation immobile ni de stabilisation finale certifiée ; pas de pause inventée. Deux plates chargées sur tout le cycle à10/20/50/100N. Aucun COP calculé, aucun décalage temporel appliqué.</p></section><h2>Comparaison diagnostique · trois vues</h2><p>Gris : marqueurs cutanés. Corail : hypothèse. Front/profil selon les axes du laboratoire, pas des repères anatomiques certifiés. Chaque vidéo contient les150frames du cycle. Vitesse lente uniquement dans le lecteur.</p>'''
for name,title in [('H0_skin_landmarks','H0 · landmarks cutanés'),('H1_static_lengths','H1 · longueurs statiques'),('H2_rigid_pelvis_static_lengths','H2 · pelvis rigide + longueurs statiques')]:
 s+=f'<section><h3>{title} — REFUSÉ comme anatomie</h3><video controls playsinline preload="metadata" poster="previews/{name}.png" src="previews/{name}.mp4"></video><button type="button" data-rate="1">Lecture ×1</button> <button type="button" data-rate="0.25">Ralenti ×0,25</button></section>'
s+='<section><h2>Inventaire complet ·37marqueurs</h2><p>100Hz ·3350samples. Positions statiques médianes en mètres. Le seuil50mm/sample est un drapeau de triage fixe, pas un critère clinique. Zéro donnée manquante ne prouve pas zéro occlusion. Tous les points de ce tableau sont des marqueurs cutanés, pas des centres articulaires.</p><div class="scroll"><table><thead><tr><th>Marqueur</th><th>Région</th><th>Statique x,y,z (m)</th><th>Manquants</th><th>Sauts &gt;50mm</th></tr></thead><tbody>'+rows+'</tbody></table></div></section><section><h2>Dossier reproductible et limites</h2><ul>'
for name,title in [('REPORT.md','Rapport et conclusions'),('RIGHTS-AND-DATA.md','Droits, attribution et données'),('RECONSTRUCTION.md','Méthodes et hypothèses'),('FORCE-AUDIT.md','Plates-formes et synchronisation'),('REPRODUCE.md','Reproduction et preuves'),('markers-report.json','Inventaire numérique complet'),('forces-report.json','Rapport forces'),('reconstruction-report.json','Résidus, angles et dynamique'),('phases-report.json','Phases'),('filter-sensitivity.json','Sensibilité indépendante au filtrage'),('model-probe.json','Chargement OpenSim'),('evidence.json','Provenance CI'),('browser-report.json','Lecture navigateur')]:s+=f'<li><a href="{name}">{title}</a></li>'
s+='''</ul><p>EN ATTENTE DE VALIDATION HUMAINE : revue professionnelle, iPhoneSafari et AndroidChrome physiques. Tests de décodage/lecture ≠ validation visuelle intégrale ou biomécanique.</p></section><footer>Florian Michaud(2026), <a href="https://zenodo.org/records/23979972">dataset v1</a>, <a href="https://creativecommons.org/licenses/by/4.0/">CC BY4.0</a>. Analyses et visualisations modifiées par PARISFIT, sans approbation des auteurs. Voir attribution complète et limites de garantie dans le dossier droits. Aucun déploiement ni fusion.</footer></main><script>document.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('click',()=>{b.closest('section').querySelector('video').playbackRate=Number(b.dataset.rate)}));</script></html>'''
(R/'index.html').write_text(s)
